def analyze_string(text):
    vowels = "aeiouAEIOU"
    vowel_count = 0
    consonant_count = 0
    digit_count = 0
    space_count = 0
    reversed_text = ""

    for char in text:
        if char in vowels:
            vowel_count += 1
        elif char.isalpha():
            consonant_count += 1
        elif char.isdigit():
            digit_count += 1
        elif char.isspace():
            space_count += 1
        reversed_text = char + reversed_text

    return {
        "vowels": vowel_count,
        "consonants": consonant_count,
        "digits": digit_count,
        "spaces": space_count,
        "reversed": reversed_text
    }

