def process_scores(scores):
    if not isinstance(scores, list):
        raise TypeError("Scores must be provided in a list.")

    cleaned_scores = []
    for s in scores:
        if not isinstance(s, (int, float)):
            raise ValueError("All scores must be numbers.")
        if s < 0 or s > 100:
            raise ValueError("Scores must be between 0 and 100.")
        cleaned_scores.append(s)

    if len(cleaned_scores) == 0:
        raise RuntimeError("No valid scores to process.")

    average = sum(cleaned_scores) / len(cleaned_scores)
    return average

