def concatenate_string_lists(list_of_lists, separator=" "):
    combined_list = []
    for sublist in list_of_lists:
        if not isinstance(sublist, list):
            continue
        filtered_items = []
        for item in sublist:
            if isinstance(item, str):
                filtered_items.append(item)
        joined_string = separator.join(filtered_items)
        combined_list.append(joined_string)
    final_result = " | ".join(combined_list)
    return final_result

