    import statistics as stats
    cleaned = []
    for value in data:
        if isinstance(value, (int, float)):
            cleaned.append(value)
    if not cleaned:
        return {
            "count": 0,
            "mean": None,
            "stdev": None,
            "sqrt_sum": None
        }
    total_sqrt = 0
    for num in cleaned:
        total_sqrt += math.sqrt(abs(num))
    return {
