    numbers = []
    while count < limit:
        if count % 2 == 0:
            numbers.append(count)
        else:
            numbers.append(count * 2)
        count += 1
    total = 0
    index = 0
    while index < len(numbers):
        total += numbers[index]
        index += 1
    return numbers, total

