    list_a = [a, b]
    list_b = [a, b]
    results['lists_equal'] = (list_a == list_b)

    dict_a = {'value1': a, 'value2': b}
    dict_b = {'value1': a, 'value2': b}
    results['dicts_equal'] = (dict_a == dict_b)

    if a == b:
        results['message'] = 'a and b are the same!'
    else:
        results['message'] = 'a and b are different.'

    return results

