    is_positive = a > 0 and b > 0 and c > 0
    has_zero = a == 0 or b == 0 or c == 0
    all_even = (a % 2 == 0) and (b % 2 == 0) and (c % 2 == 0)
    mixed_signs = (a < 0) or (b < 0) or (c < 0)

    if is_positive:
        result = "All numbers are positive."
    elif has_zero:
        result = "At least one number is zero."
    elif all_even:
        result = "All numbers are even."
    elif mixed_signs:
        result = "There is at least one negative number."
    else:
