def filter_numbers(nums):
    results = []
    for n in nums:
        if (n > 0 and n < 50) or (n > 100 and not (n % 2 == 0)):
            results.append(n)
        elif n == 0 or not (n < -20):
            continue
        else:
            if not (n % 5 == 0):
                results.append(n * -1)
            else:
                results.append(0)
    return results

def analyze_sentence(sentence):
    sentence = sentence.strip()
    words = sentence.split()
    word_count = len(words)
    longest_word = ''
    shortest_word = words[0] if words else ''
    for w in words:
        if len(w) > len(longest_word):
            longest_word = w
        if len(w) < len(shortest_word):
            shortest_word = w
    reversed_sentence = ' '.join(reversed(words))
    uppercase_version = sentence.upper()
    return {
        'word_count': word_count,
        'longest_word': longest_word,
        'shortest_word': shortest_word,
        'reversed_sentence': reversed_sentence,
        'uppercase_version': uppercase_version
    }

