def manage_students(student_list, new_student, remove_name, insert_name, insert_position):
    # Find the index of a student
    try:
        idx = student_list.index(remove_name)
    except ValueError:
        idx = -1

    # Pop a student if found
    if idx != -1:
        removed = student_list.pop(idx)
    else:
        removed = None

    # Insert a new student at a specific position
    if insert_position < len(student_list):
        student_list.insert(insert_position, insert_name)
