    reversed_sentence = sentence[::-1]
    vowel_count = 0
    for ch in sentence.lower():
        if ch in "aeiou":
            vowel_count += 1
    return {
        "characters": char_count,
        "words": word_count,
        "longest_word": longest_word,
        "reversed": reversed_sentence,
        "vowels": vowel_count
    }

