def simulate_lottery_draw(num_tickets):
    import random
    winning_numbers = []
    for _ in range(6):
        number = random.randint(1, 49)
        while number in winning_numbers:
            number = random.randint(1, 49)
        winning_numbers.append(number)
    ticket_results = {}
    for ticket_id in range(1, num_tickets + 1):
        matches = 0
        for _ in range(6):
