def analyze_string(text):
    vowels = "aeiouAEIOU"
    vowel_count = 0
    consonant_count = 0
    reversed_text = ""
    for char in text:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1
        reversed_text = char + reversed_text
    uppercase_version = text.upper()
    no_space_version = text.replace(" ", "")
    return vowel_count, consonant_count, reversed_text, uppercase_version, no_space_version

