def process_text(text_list, target_word, replacement_word):
    combined = " ".join(text_list)
    position = combined.find(target_word)
    swapped = combined.swapcase()
    replaced = combined.replace(target_word, replacement_word)
    words = replaced.split(" ")
    result = []
    for w in words:
        if w.lower() != replacement_word.lower():
            result.append(w)
        else:
            result.append(w.upper())
    final_output = "-".join(result)
    return {
        "original": combined,
        "found_at": position,
        "swapped": swapped,
        "replaced": replaced,
        "final_output": final_output
    }

