def summarize_grades(student_grades):
    subject_counts = {}
    total_scores = {}
    for student, grades in student_grades.items():
        for subject, score in grades.items():
            if subject not in subject_counts:
                subject_counts[subject] = 0
                total_scores[subject] = 0
            subject_counts[subject] += 1
            total_scores[subject] += score
    averages = {}
    for subject in total_scores:
        averages[subject] = total_scores[subject] / subject_counts[subject]
    return averages

def analyze_students(scores):
    student_data = {}
    for name, score in scores:
        if name not in student_data:
            student_data[name] = {'total': 0, 'count': 0}
        student_data[name]['total'] += score
        student_data[name]['count'] += 1
    averages = {}
    for name, data in student_data.items():
        averages[name] = data['total'] / data['count']
    highest = max(averages, key=averages.get)
    return averages, highest

