def analyze_scores(scores):
    total = 0
    highest = 0
    count_above_80 = 0
    for score in scores:
        total += score
        if score > highest:
            highest = score
        if score > 80:
            count_above_80 += 1
    average = total / len(scores)
    for i in range(len(scores)):
        if scores[i] < 50:
            scores[i] += 5
    return average, highest, count_above_80, scores

