def concat_string_lists(list1, list2):
    combined = []
    for item in list1:
        combined.append(item)
    for item in list2:
        combined.append(item)
    result = ""
    for element in combined:
        if isinstance(element, str):
            result += element + " "
        else:
            result += str(element) + " "
    return result.strip()

