def find_items_in_list(items, queries):
    results = {}
    for query in queries:
        if query in items:
            results[query] = True
        else:
            results[query] = False
    count_present = 0
    for key in results:
        if results[key] is True:
            count_present += 1
    summary = f"{count_present} out of {len(queries)} queries were found."
    return results, summary

