def process_text(text_list, search_word, replacement):
    combined = " ".join(text_list)
    index = combined.find(search_word)
    if index == -1:
        result = combined.replace(search_word, replacement)
    else:
        result = combined.replace(search_word, replacement)
    parts = result.split(" ")
    swapped_parts = []
    for p in parts:
        swapped_parts.append(p.swapcase())
    final_text = " ".join(swapped_parts)
    return final_text

