def analyze_keywords_in_text(text):
    import keyword
    words = text.split()
    keyword_count = 0
    found_keywords = []
    for w in words:
        if w in keyword.kwlist:
            keyword_count += 1
            found_keywords.append(w)
    print("Total Python keywords found:", keyword_count)
    if found_keywords:
        print("Keywords detected:")
        for k in found_keywords:
            print("-", k)
    else:
        print("No Python keywords detected in the text.")
    return found_keywords

