def analyze_imports(module_names):
    imported_modules = {}
    for name in module_names:
        try:
            module = __import__(name)
            functions = [attr for attr in dir(module) if callable(getattr(module, attr))]
            imported_modules[name] = {
                'module': module,
                'function_count': len(functions),
                'functions': functions[:5]
            }
        except ImportError:
            imported_modules[name] = {
                'error': f'Could not import module: {name}'
            }
    for name, info in imported_modules.items():
        if 'error' in info:
            print(info['error'])
        else:
            print(f"Module: {name} | Functions found: {info['function_count']}")
    return imported_modules

