def transform_numbers(numbers):
    def square(n):
        return n * n

    def is_even(n):
        return n % 2 == 0

    squared_numbers = list(map(square, numbers))
    even_flags = list(map(is_even, numbers))

    combined = []
    for num, sq, even in zip(numbers, squared_numbers, even_flags):
        combined.append((num, sq, even))

    return combined

