def analyze_conditions(a, b, c):
    is_positive = a > 0 and b > 0 and c > 0
    all_equal = a == b == c
    at_least_one_zero = (a == 0) or (b == 0) or (c == 0)
    majority_positive = (a > 0) + (b > 0) + (c > 0) >= 2
    mixed_signs = (a > 0 and (b < 0 or c < 0)) or (b > 0 and (a < 0 or c < 0))
    no_negatives = not (a < 0 or b < 0 or c < 0)

    if all_equal:
        return "All numbers are equal"
    elif is_positive:
        return "All numbers are positive"
    elif at_least_one_zero:
        return "There is at least one zero"
    elif majority_positive:
        return "Most numbers are positive"
    elif mixed_signs:
        return "There is a mix of positive and negative numbers"
    elif no_negatives:
        return "There are no negative numbers"
    else:
        return "The numbers have varied conditions"

