    code_count = 0
    empty_count = 0
    combined = []
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('#'):
            comment_count += 1
            combined.append((line, 'comment'))
        elif stripped == '':
            empty_count += 1
            combined.append((line, 'empty'))
        else:
            code_count += 1
            combined.append((line, 'code'))
    summary = {
        'comments': comment_count,
        'code_lines': code_count,
        'empty_lines': empty_count,
        'detailed': combined
    }
    return summary

