def analyze_comments(code_lines):
    # Initialize counters for total lines and commented lines
    total_lines = len(code_lines)
    commented_lines = 0

    # Loop through each line of code
    for line in code_lines:
        # Strip whitespace to avoid counting indented spaces
        stripped = line.strip()

        # Check if the line starts with a comment symbol
        if stripped.startswith('#'):
            commented_lines += 1

    # Calculate the percentage of commented lines
    if total_lines > 0:
        percentage = (commented_lines / total_lines) * 100
    else:
        percentage = 0

    # Return a summary as a dictionary
    return {
        'total_lines': total_lines,
        'commented_lines': commented_lines,
        'percentage_commented': percentage
    }

