def compare_values(a, b):
    results = {}
    results['numbers_equal'] = (a == b)
    results['string_equal'] = (str(a) == str(b))
    results['type_equal'] = (type(a) == type(b))

    list_a = [a, b]
    list_b = [a, b]
    list_c = [b, a]

    results['lists_same_order'] = (list_a == list_b)
    results['lists_diff_order'] = (list_a == list_c)

    dict_a = {'x': a, 'y': b}
    dict_b = {'x': a, 'y': b}
    dict_c = {'y': b, 'x': a}

    results['dicts_equal'] = (dict_a == dict_b)
    results['dicts_order_irrelevant'] = (dict_a == dict_c)

    return results

