def analyze_text(s):
    vowels = 'aeiouAEIOU'
    vowel_count = 0
    consonant_count = 0
    reversed_text = ''
    longest_word = ''

    for char in s:
        if char in vowels:
            vowel_count += 1
        elif char.isalpha():
            consonant_count += 1

    for i in range(len(s) - 1, -1, -1):
        reversed_text += s[i]

    words = s.split()
    for word in words:
        if len(word) > len(longest_word):
            longest_word = word

    return vowel_count, consonant_count, reversed_text, longest_word

