def access_control(age, has_permission, is_banned, override=False):
    if override or (age >= 18 and not is_banned):
        if has_permission or override:
            allowed = True
        else:
            allowed = False
    else:
        allowed = False

    if not allowed:
        reason = "Access denied"
        if is_banned and not override:
            reason += " because the user is banned."
        elif age < 18 and not override:
            reason += " because the user is under 18."
        elif not has_permission and not override:
            reason += " due to missing permissions."
    else:
        reason = "Access granted."

    return allowed, reason

