def read_and_process_file(filename):
    results = []
    with open(filename, 'r') as file:
        for line in file:
            cleaned = line.strip()
            if cleaned:
                length = len(cleaned)
                results.append((cleaned, length))
    with open('summary.txt', 'w') as summary:
        for text, length in results:
            summary.write(f"{text} -> {length} characters\n")
    return results

