def filter_numbers(nums):
    results = []
    for n in nums:
        is_even = (n % 2 == 0)
        is_large = (n > 50)
        is_negative = (n < 0)
        if (is_even or is_large) and not is_negative:
            results.append(n)
        elif not is_even and not is_large:
            results.append(-1)
        else:
            results.append(0)
    return results

