def manage_inventory():
    inventory = {'apples': 10, 'bananas': 6, 'oranges': 4}
    print('Current items:', inventory.items())
    print('Item names:', inventory.keys())
    print('Item quantities:', inventory.values())

    new_stock = {'bananas': 10, 'grapes': 7}
    inventory.update(new_stock)
    print('After update:', inventory)

    removed = inventory.pop('oranges', None)
    print('Removed item quantity:', removed)

    for item, qty in inventory.items():
        print('We have', qty, 'of', item)

    return inventory

