def process_numbers(num_list):
    results = []
    for item in num_list:
        try:
            number = int(item)
            if number % 2 == 0:
                results.append((number, 'even'))
            else:
                results.append((number, 'odd'))
        except ValueError:
            results.append((item, 'not convertible'))
    total = 0
    for value, status in results:
        if status == 'even' or status == 'odd':
            total += value
    return results, total

