def calculate_student_average(grades):
    total = 0
    for score in grades:
        total += score
    if len(grades) == 0:
        return 0
    return total / len(grades)

def compare_averages(avg1, avg2):
    if avg1 > avg2:
        return "Student 1 has the higher average."
    elif avg2 > avg1:
        return "Student 2 has the higher average."
    else:
        return "Both students have the same average."

def main():
    student1 = [88, 92, 79, 85]
    student2 = [91, 87, 90, 80]
    avg1 = calculate_student_average(student1)
    avg2 = calculate_student_average(student2)
    result = compare_averages(avg1, avg2)
    return result

def average_as_float(numbers):
    total = 0
    for n in numbers:
        total += float(n)
    count = float(len(numbers))
    if count == 0:
        return 0.0
    avg = total / count
    return avg

