        task_list.append(task)
    for task in tasks_to_remove:
        if task in task_list:
            task_list.remove(task)
    cleaned_tasks = []
    for t in task_list:
        if len(t) > 0:
            cleaned_tasks.append(t)
    while "" in cleaned_tasks:
        cleaned_tasks.remove("")
    return cleaned_tasks

