def manage_task_list(tasks):
    task_list = []

    for task in tasks:
        if task not in task_list:
            task_list.append(task)
        else:
            print("Task already exists:", task)

    print("Initial list:", task_list)

    for task in tasks:
        if len(task) < 5 and task in task_list:
            task_list.remove(task)

    print("Final list after removals:", task_list)
    return task_list

